declare
  old_rev record;
  v_rev integer;
  v_blocks jsonb := $b83$[{"t": "list", "id": "a2-2-4-4-b7", "imp": "core", "items": ["1、线性表及其顺序存储结构", "（1）^^线性表：^^==由一组数据元素构成，数据元素的位置只取决于自己的序号，元素之间的相对位置是线性的。==", "（2）^^在复杂线性表中，由若干项数据元素组成的数据元素称为记录；由多个记录构成的线性表称为文件。^^", "（3）非空线性表的结构特征：", "==①、有且只有一个根结点 \\(a_1\\)，它无前件==", "==②、有且只有一个终端结点 \\(a_n\\)，它无后件；==", "==③、除根结点与终端结点外，其他所有结点有且只有一个前件，也有且只有一个后件。==", "（4）结点个数 \\(n\\) 称为线性表的长度，当 \\(n = 0\\) 时，称为空表", "（5）^^线性表的^^==顺序存储结构==^^具有以下两个基本特点：^^", "==①、线性表中所有元素所占的存储空间是连续的；==", "==②、线性表中各数据元素在存储空间中是按逻辑顺序依次存放的。==", "（6）^^线性表存储结构实现的举例：^^", "^^①、^^==数组==^^：有序存储，占有一片连继地址，顺序存储结构的。^^", "^^②、^^==链表==^^：无序存放的元素关联起来，链式存储结构的。^^", "^^③、^^==栈==^^：先进先出(限定在一端)，链式结构或顺序存储结构。^^", "（7）线性表的运算与操作", "①、顺序表的运算：查找、插入、删除、合并、排序、复制、逆转等", "②、原则：运算后仍操持线性表的特性", "③、示例："], "title": "", "ordered": false}, {"h": 688, "t": "img", "w": 2000, "id": "a2-2-4-4-b8", "imp": "normal", "src": "/kb-assets/theory/p40_r0_6584dce1f1577f8c.png", "title": ""}, {"t": "list", "id": "a2-2-4-4-b9", "imp": "core", "items": ["2、==栈==", "==（1）栈是一种特殊的线性表，只允许在表的一端进行插入和删除的线性表；插入，删除的一端为栈顶，另一端为栈底；当表中没有元素时为空栈。==", "==（2）栈是一种==@@后进先出@@==（或先进后出Last In First Out）的线性表。栈具有记忆功能。==", "（3）^^栈的存储结构：^^", "^^①、顺序存储结构：用一组地址连续的存储单元即一维数组来存储；^^", "^^②、链式存储：用线性链表来存储；^^", "（4）栈的基本运算", "①、==入栈运算==，在栈顶位置插入元素；", "②、==退栈运算==，删除元素(取出栈顶元素并赋给一个指定的变量)；", "③、==读栈顶元素==，将栈顶元素赋给一个指定的变量，此时指针无变化。", "（5）运算举例："], "title": "", "ordered": false}, {"h": 766, "t": "img", "w": 2000, "id": "a2-2-4-4-b10", "imp": "normal", "src": "/kb-assets/theory/p40_r1_6a1300234d7d81c9.png", "title": ""}, {"t": "list", "id": "a2-2-4-4-b11", "imp": "core", "items": ["3、==队列==", "（1）==队列是一种特殊的线性表，只允许在表的一端插入，在另一端删除，允许插入的一端是队尾（rear），允许删除的一端为队头（front）；当表中没有元素是空队列；队列是一种==@@先进先出@@==的线性表。(FIFO)==", "（2）^^队列的存储结构：^^", "^^①、顺序存储结构：一维数组^^", "^^②、链式存储：线性链表；^^", "（3）==队列的顺序存储结构一般采用循环队列的形式==。循环队列s=0 表示队列为空；s=1 且front=rear 表示队满。", "（4）队列的基本运算", "==①、入队运算：从队尾插入一个元素；==", "==②、退队运算：从队头删除一个元素==", "==③、取读队头元素==", "（5）计算循环队列的元素个数：“尾指针减头指针”，若为负数，再加其容量即可。", "==队列长度（元素个数）= \\((m + \\text{rear} - \\text{front}) \\% m\\)==（\\(m\\) 为总长度）。"], "title": "", "ordered": false}, {"h": 292, "t": "img", "w": 325, "id": "a2-2-4-4-b12", "imp": "normal", "src": "/kb-assets/theory/p41_r0_8357e9dc08937efd.png", "title": ""}, {"t": "list", "id": "a2-2-4-4-b13", "imp": "normal", "items": ["（6）运行举例："], "title": "", "ordered": false}, {"h": 295, "t": "img", "w": 676, "id": "a2-2-4-4-b14", "imp": "normal", "src": "/kb-assets/theory/p41_r1_bdf774f2833554cf.png", "title": ""}, {"t": "callout", "id": "a2-2-4-4-b15", "imp": "core", "kind": "tip", "text": "• ==栈（Stack）==：限定仅在表的一端（栈顶 Top）进行插入与删除，遵循==后进先出（LIFO，Last In First Out）==，常用于函数调用、递归实现、表达式求值、括号匹配； • ==队列（Queue）==：在一端（队尾 Rear）入队，另一端（队头 Front）出队，遵循==先进先出（FIFO，First In First Out）==，常用于缓冲区调度与广度优先遍历。", "title": "考向复习提示：栈（LIFO）与队列（FIFO）的操作特性"}, {"t": "callout", "id": "a2-2-4-4-b16", "imp": "core", "kind": "trap", "text": "若 n 个不同元素依次进栈（进出栈可以穿插交替进行），其所有合法的出栈序列种类数恰好等于==卡特兰数（Catalan Number）：\\(C(n) = \\frac{1}{n + 1} \\times C(2n, n)\\)==；当 n=3（元素 1,2,3）时，合法出栈序列种类数为 \\(\\frac{1}{4} \\times C(6, 3) = 5\\) 种，不可能出现的非法序列是 `3,1,2`！", "title": "高频易错陷阱：出栈合法序列的经典组合数计算"}]$b83$::jsonb;
  v_search text := $s83$A2-2.4.4 栈和队列的定义，栈和队列的顺序存储结构及其基本运算。 1、线性表及其顺序存储结构 （1）线性表：由一组数据元素构成，数据元素的位置只取决于自己的序号，元素之间的相对位置是线性的。 （2）在复杂线性表中，由若干项数据元素组成的数据元素称为记录；由多个记录构成的线性表称为文件。 （3）非空线性表的结构特征： ①、有且只有一个根结点 a_1，它无前件 ②、有且只有一个终端结点 a_n，它无后件； ③、除根结点与终端结点外，其他所有结点有且只有一个前件，也有且只有一个后件。 （4）结点个数 n 称为线性表的长度，当 n = 0 时，称为空表 （5）线性表的顺序存储结构具有以下两个基本特点： ①、线性表中所有元素所占的存储空间是连续的； ②、线性表中各数据元素在存储空间中是按逻辑顺序依次存放的。 （6）线性表存储结构实现的举例： ①、数组：有序存储，占有一片连继地址，顺序存储结构的。 ②、链表：无序存放的元素关联起来，链式存储结构的。 ③、栈：先进先出(限定在一端)，链式结构或顺序存储结构。 （7）线性表的运算与操作 ①、顺序表的运算：查找、插入、删除、合并、排序、复制、逆转等 ②、原则：运算后仍操持线性表的特性 ③、示例： 2、栈 （1）栈是一种特殊的线性表，只允许在表的一端进行插入和删除的线性表；插入，删除的一端为栈顶，另一端为栈底；当表中没有元素时为空栈。 （2）栈是一种后进先出（或先进后出Last In First Out）的线性表。栈具有记忆功能。 （3）栈的存储结构： ①、顺序存储结构：用一组地址连续的存储单元即一维数组来存储； ②、链式存储：用线性链表来存储； （4）栈的基本运算 ①、入栈运算，在栈顶位置插入元素； ②、退栈运算，删除元素(取出栈顶元素并赋给一个指定的变量)； ③、读栈顶元素，将栈顶元素赋给一个指定的变量，此时指针无变化。 （5）运算举例： 3、队列 （1）队列是一种特殊的线性表，只允许在表的一端插入，在另一端删除，允许插入的一端是队尾（rear），允许删除的一端为队头（front）；当表中没有元素是空队列；队列是一种先进先出的线性表。(FIFO) （2）队列的存储结构： ①、顺序存储结构：一维数组 ②、链式存储：线性链表； （3）队列的顺序存储结构一般采用循环队列的形式。循环队列s=0 表示队列为空；s=1 且front=rear 表示队满。 （4）队列的基本运算 ①、入队运算：从队尾插入一个元素； ②、退队运算：从队头删除一个元素 ③、取读队头元素 （5）计算循环队列的元素个数：“尾指针减头指针”，若为负数，再加其容量即可。 队列长度（元素个数）= (m + rear - front) % m（m 为总长度）。 （6）运行举例： 考向复习提示：栈（LIFO）与队列（FIFO）的操作特性 • 栈（Stack）：限定仅在表的一端（栈顶 Top）进行插入与删除，遵循后进先出（LIFO，Last In First Out），常用于函数调用、递归实现、表达式求值、括号匹配； • 队列（Queue）：在一端（队尾 Rear）入队，另一端（队头 Front）出队，遵循先进先出（FIFO，First In First Out），常用于缓冲区调度与广度优先遍历。 高频易错陷阱：出栈合法序列的经典组合数计算 若 n 个不同元素依次进栈（进出栈可以穿插交替进行），其所有合法的出栈序列种类数恰好等于卡特兰数（Catalan Number）：C(n) = 1/(n+1) × C(2n, n)；当 n=3（元素 1,2,3）时，合法出栈序列种类数为 1/4 × C(6, 3) = 5 种，不可能出现的非法序列是 3,1,2！$s83$;
  v_sr jsonb := $r83${"pdf": "理论复习.pdf", "extra": ["考纲三级节点: A2-2.4.4 栈和队列的定义，栈和队列的顺序存储结构及其基本运算。"], "pages": [39, 40, 41], "spans": 58}$r83$::jsonb;
begin
  select r.rev_no, r.html
    into old_rev
    from kb_entry e
    join kb_revision r on r.node_id = e.node_id and r.rev_no = e.published_rev
   where e.node_id = 83;

  if not found then
    raise exception 'node 83 找不到已发布 revision';
  end if;
  if old_rev.rev_no <> 9 then
    raise exception 'node 83 expected rev 9, got %', old_rev.rev_no;
  end if;

  select coalesce(max(rev_no), 0) + 1 into v_rev
    from kb_revision
   where node_id = 83;

  insert into kb_revision (node_id, rev_no, blocks, html, search_text, source_ref)
  values (83, v_rev, v_blocks, old_rev.html, v_search, v_sr);

  update kb_entry
     set published_rev = v_rev,
         updated_at = now()
   where node_id = 83;
end $$;

do $$
declare
  old_rev record;
  v_rev integer;
  v_blocks jsonb := $b84$[{"t": "list", "id": "a2-2-4-5-b1", "imp": "core", "title": "", "ordered": false, "items": ["1、^^线性链表^^", "（1）^^线性链表是线性表的链式存储结构，数据结构中的每一个结点对应于一个存储单元，这种存储单元称为存储结点，简称结点。^^结点由两部分组成：", "①、用于存储数据元素值，称为==数据域==；", "②、用于存放指针，称为==指针域==，用于指向前一个或后一个结点。", "（2）在链式存储结构中，存储数据结构的==存储空间可以不连续==，各数据结点的存储顺序与数据元素之间的逻辑关系可以不一致，而数据元素之间的逻辑关系是由指针域来确定的。链式存储方式既可以用于表示线性结构，也可用于表示非线性结构。", "（3）线性单链表中，HEAD 称为头指针，HEAD=NULL（或0）称为空表。"]}, {"h": 146, "t": "img", "w": 1350, "id": "a2-2-4-5-b2", "imp": "normal", "src": "/kb-assets/theory/p41_r2_c6d42e6dfad714b4.png", "title": ""}, {"t": "list", "id": "a2-2-4-5-b3", "imp": "core", "items": ["（4）对线性链表中的每个结点设置==两个指针==，==一个称为左指针，用以指向其前件结点==；另一个称为==右指针，用以指向其后件结点==。这样的表称为==双向链表==。", "双向链表有两个指针：==左指针（Llink）指向前件结点==，==右指针（Rlink）指向后件结点==。"], "title": "", "ordered": false}, {"h": 140, "t": "img", "w": 1012, "id": "a2-2-4-5-b4", "imp": "normal", "src": "/kb-assets/theory/p42_r0_680aaa084c100db4.png", "title": ""}, {"t": "list", "id": "a2-2-4-5-b5", "imp": "core", "items": ["（5）在线性链表中，其插入与删除的运算虽然比较方便，但还存在一个问题，在运算过程中对于空表和对第一个结点的处理必须单独考虑，使空表与非空表的运算不统一。为了克服线性链表的这个缺点，可以采用另一种链接方式，即循环链表。", "循环链表具有以下两个特点：", "①、在==链表中增加了一个表头结点==，其数据域为任意或者根据需要来设置，指针域指向线性表的第一个元素的结点，而==循环链表的头指针指向表头结点==；", "②、循环链表中==最后一个结点的指针域不是空==，而是==指向表头结点==。即在循环链表中，所有结点的指针构成了一个环状链。", "循环链表：==循环链表与单链表的不同的是它的最后一个结点的指针域存放的是指向第一个结点的指针而单链表存放的是空指针。=="], "title": "", "ordered": false}, {"h": 187, "t": "img", "w": 1129, "id": "a2-2-4-5-b6", "imp": "normal", "src": "/kb-assets/theory/p42_r1_b0a09ffb421d72d1.png", "title": ""}, {"t": "list", "id": "a2-2-4-5-b7", "imp": "core", "items": ["（6）线性链表的基本运算：==查找、插入、删除==。", "（7）运行举例：", "①、插入："], "title": "", "ordered": false}, {"h": 226, "t": "img", "w": 620, "id": "a2-2-4-5-b8", "imp": "normal", "src": "/kb-assets/theory/p42_r2_c6eb2894f4763252.png", "title": ""}, {"t": "list", "id": "a2-2-4-5-b9", "imp": "normal", "items": ["②、删除："], "title": "", "ordered": false}, {"h": 228, "t": "img", "w": 673, "id": "a2-2-4-5-b10", "imp": "normal", "src": "/kb-assets/theory/p42_r3_88addf917583aa9c.png", "title": ""}, {"t": "list", "id": "a2-2-4-5-b11", "imp": "core", "title": "", "ordered": false, "items": ["2、==线性单链表、双向链表与循环链表的结构及基本运算==：==单链表是一种链式存取的数据结构==，用一组地址任意的存储单元存放线性表中的数据元素。 双向链表从任意一个结点出发，都可以方便地访问它的前驱结点和后继结点。 单链表最后一个结点的指针指向 NULL；循环链表最后一个结点的指针指向头结点，首尾相连，形成环状链。", "3、==链表的组成与结束标志==：==链表把无序存放的数据元素关联起来==，建立先后顺序。", "① ==链表中的每个数据元素 = 数据 + 指针==。", "② ==链表最后一个数据元素的指针为空==。"]}, {"t": "callout", "id": "a2-2-4-5-b12", "imp": "core", "kind": "tip", "text": "• ==顺序表（数组）==：占用连续内存，==支持 \\(O(1)\\) 随机存取==；但插入和删除需成批移动数据，时间复杂度为 \\(O(n)\\)，且容量静态固定； • ==链表（单链表）==：内存节点离散分布，通过指针串联，==插入和删除只需修改指针 \\(O(1)\\)==；但不支持随机存取（查找为 \\(O(n)\\)），且需要指针域额外开销。", "title": "考向复习提示：顺序表 vs 链表的核心性能对比"}, {"t": "callout", "id": "a2-2-4-5-b13", "imp": "core", "kind": "trap", "text": "单链表在节点 p 后插入节点 s：==必须先将 s 的后继指针指向 p 的后继，再将 p 的后继指向 s==（即 `s->next = p->next; p->next = s;`）；若将两句顺序颠倒，会导致原链表后续节点地址彻底丢失（内存泄露断链）！", "title": "高频易错陷阱：链表节点的插入与删除指针修改顺序"}]$b84$::jsonb;
  v_search text := $s84$A2-2.4.5 线性单链表、双向链表与循环链表的结构及其基本运算。 1、线性链表 （1）线性链表是线性表的链式存储结构，数据结构中的每一个结点对应于一个存储单元，这种存储单元称为存储结点，简称结点。结点由两部分组成： ①、用于存储数据元素值，称为数据域； ②、用于存放指针，称为指针域，用于指向前一个或后一个结点。 （2）在链式存储结构中，存储数据结构的存储空间可以不连续，各数据结点的存储顺序与数据元素之间的逻辑关系可以不一致，而数据元素之间的逻辑关系是由指针域来确定的。链式存储方式既可以用于表示线性结构，也可用于表示非线性结构。 （3）线性单链表中，HEAD 称为头指针，HEAD=NULL（或0）称为空表。 （4）对线性链表中的每个结点设置两个指针，一个称为左指针，用以指向其前件结点；另一个称为右指针，用以指向其后件结点。这样的表称为双向链表。 双向链表有两个指针：左指针（Llink）指向前件结点，右指针（Rlink）指向后件结点。 （5）在线性链表中，其插入与删除的运算虽然比较方便，但还存在一个问题，在运算过程中对于空表和对第一个结点的处理必须单独考虑，使空表与非空表的运算不统一。为了克服线性链表的这个缺点，可以采用另一种链接方式，即循环链表。 循环链表具有以下两个特点： ①、在链表中增加了一个表头结点，其数据域为任意或者根据需要来设置，指针域指向线性表的第一个元素的结点，而循环链表的头指针指向表头结点； ②、循环链表中最后一个结点的指针域不是空，而是指向表头结点。即在循环链表中，所有结点的指针构成了一个环状链。 循环链表：循环链表与单链表的不同的是它的最后一个结点的指针域存放的是指向第一个结点的指针而单链表存放的是空指针。 （6）线性链表的基本运算：查找、插入、删除。 （7）运行举例： ①、插入： ②、删除： 2、线性单链表、双向链表与循环链表的结构及基本运算：单链表是一种链式存取的数据结构，用一组地址任意的存储单元存放线性表中的数据元素。 双向链表从任意一个结点出发，都可以方便地访问它的前驱结点和后继结点。 单链表最后一个结点的指针指向 NULL；循环链表最后一个结点的指针指向头结点，首尾相连，形成环状链。 3、链表的组成与结束标志：链表把无序存放的数据元素关联起来，建立先后顺序。 ① 链表中的每个数据元素 = 数据 + 指针。 ② 链表最后一个数据元素的指针为空。 考向复习提示：顺序表 vs 链表的核心性能对比 • 顺序表（数组）：占用连续内存，支持 O(1) 随机存取；但插入和删除需成批移动数据，时间复杂度为 O(n)，且容量静态固定； • 链表（单链表）：内存节点离散分布，通过指针串联，插入和删除只需修改指针 O(1)；但不支持随机存取（查找为 O(n)），且需要指针域额外开销。 高频易错陷阱：链表节点的插入与删除指针修改顺序 单链表在节点 p 后插入节点 s：必须先将 s 的后继指针指向 p 的后继，再将 p 的后继指向 s（即 s->next = p->next; p->next = s;）；若将两句顺序颠倒，会导致原链表后续节点地址彻底丢失（内存泄露断链）！$s84$;
  v_sr jsonb := $r84${"pdf": "理论复习.pdf", "extra": ["考纲三级节点: A2-2.4.5 线性单链表、双向链表与循环链表的结构及其基本运算。", "题库补充：线性单链表、双向链表与循环链表的结构及基本运算 (18题)", "题库补充：链表的组成与结束标志 (12题)"], "pages": [41, 42], "spans": 18}$r84$::jsonb;
begin
  select r.rev_no, r.html
    into old_rev
    from kb_entry e
    join kb_revision r on r.node_id = e.node_id and r.rev_no = e.published_rev
   where e.node_id = 84;

  if not found then
    raise exception 'node 84 找不到已发布 revision';
  end if;
  if old_rev.rev_no <> 3 then
    raise exception 'node 84 expected rev 3, got %', old_rev.rev_no;
  end if;

  select coalesce(max(rev_no), 0) + 1 into v_rev
    from kb_revision
   where node_id = 84;

  insert into kb_revision (node_id, rev_no, blocks, html, search_text, source_ref)
  values (84, v_rev, v_blocks, old_rev.html, v_search, v_sr);

  update kb_entry
     set published_rev = v_rev,
         updated_at = now()
   where node_id = 84;
end $$;

do $$
declare
  old_rev record;
  v_rev integer;
  v_blocks jsonb := $b85$[{"t": "list", "id": "a2-2-4-6-b1", "imp": "core", "items": ["1、^^树^^", "（1）==树是一种非线性结构，是n 个结点的有限集。当n=0 时为空树，n>0 时为非空树。==", "①、结点的度：结点所拥有的子树的个数，数一下分叉个数，如结点1 的有三个叉，即为3.", "②、==叶子结点==：度为0 的结点,即没有下一代无后继无分叉。如图3，5，6，7，8 结点。", "③、分支结点：除叶子结点以外的结点。", "④、结点的层次：根结点在第一层，同一层上左右结点的子结点在下一层。", "⑤、==树的深度==：所处层次最大的那个结点的层次。从根节点（结点1）开始数有多少层，就是多少深度，如图上所示，有三层。即深度为3。", "⑥、==树的度==：树中所有结点的度的最大值。即1 结点有三个子结点（2，3，4），且为最大，度为3。"], "title": "", "ordered": false}, {"h": 414, "t": "img", "w": 612, "id": "a2-2-4-6-b2", "imp": "normal", "src": "/kb-assets/theory/p43_r0_3937205f6da1b19e.png", "title": ""}, {"t": "list", "id": "a2-2-4-6-b3", "imp": "core", "items": ["（2）==二叉树是一种特殊的树形结构，每个结点最多只有两棵子树，且有左右之分不能互换，因此，二叉树有五种不同的形态。==", "①、性质1 在二叉树的第k 层上，最多有\\(2^{k-1}\\)（\\(k \\ge 1\\)）个结点。", "②、性质2 深度为 \\(m\\) 的二叉树最多有 \\(2^m - 1\\) 个结点。", "③、性质3 在任意一棵二叉树中，度为0 的结点（叶子结点）总是比度为2 的结点多一个。", "④、性质4 具有 \\(n\\) 个结点的二叉树，其深度不小于 \\([\\log_2 n] + 1\\)，其中 \\([\\log_2 n]\\) 表示为 \\(\\log_2 n\\) 的整数部分。", "（3）==满二叉树：除最后一层外，每一层上的所有结点都有两个子结点。=="], "title": "", "ordered": false}, {"h": 452, "t": "img", "w": 534, "id": "a2-2-4-6-b4", "imp": "normal", "src": "/kb-assets/theory/p43_r1_e3e2604f053ee3c0.png", "title": ""}, {"t": "list", "id": "a2-2-4-6-b5", "imp": "hard", "items": ["（4）@@完全二叉树:除最后一层外，每一层上的结点数均达到最大值；在最后一层上只缺少右边(连续)的若干结点。@@", "①、性质1 具有 \\(n\\) 个结点的完全二叉树的深度为 \\([\\log_2 n] + 1\\)。", "②、性质2 完全二叉树中度为1 的结点数为0 或1。"], "title": "", "ordered": false}, {"h": 426, "t": "img", "w": 811, "id": "a2-2-4-6-b6", "imp": "normal", "src": "/kb-assets/theory/p43_r2_6ca5b2e8759be6d8.png", "title": ""}, {"t": "list", "id": "a2-2-4-6-b7", "imp": "hard", "items": ["（5）@@满二叉树是完全二叉树，而完全二叉树一般不是满二叉树。@@", "（6）@@二叉树遍历：前序、中序和后序@@", "①、@@前序遍历@@：先访问根结点、然后遍历左子树，最后遍历右子树；并且，在遍历左、右子树时，仍然先访问根结点，然后遍历左子树，最后遍历右子树。（根-左-右）"], "title": "", "ordered": false}, {"h": 444, "t": "img", "w": 363, "id": "a2-2-4-6-b8", "imp": "normal", "src": "/kb-assets/theory/p44_r0_760fa8fa12b1adf2.png", "title": ""}, {"t": "list", "id": "a2-2-4-6-b9", "imp": "hard", "items": ["^^前序遍历结果：ABCDFHEG^^", "②、@@中序遍历@@：先遍历左子树、然后访问根结点，最后遍历右子树；并且，在遍历左、右子树时，仍然先遍历左子树，然后访问根结点，最后遍历右子树。 （左-根-右）"], "title": "", "ordered": false}, {"h": 469, "t": "img", "w": 384, "id": "a2-2-4-6-b10", "imp": "normal", "src": "/kb-assets/theory/p44_r1_8a56866145b7874c.png", "title": ""}, {"t": "list", "id": "a2-2-4-6-b11", "imp": "hard", "items": ["^^中序遍历结果：BAFHDCGE^^", "③、@@后序遍历@@：先遍历左子树、然后遍历右子树，最后访问根结点；并且，在遍历左、右子树时，仍然先遍历左子树，然后遍历右子树，最后访问根结点。 （左-右-根）"], "title": "", "ordered": false}, {"h": 454, "t": "img", "w": 372, "id": "a2-2-4-6-b12", "imp": "normal", "src": "/kb-assets/theory/p44_r2_5f4cf27f5a5ff6ba.png", "title": ""}, {"t": "list", "id": "a2-2-4-6-b13", "imp": "core", "items": ["^^后序遍历结果：BHFDGECA^^", "2、==完全二叉树的顺序存储与遍历==：^^完全二叉树的顺序存储^^：从树根开始自上而下、每层从左至右给每个结点编号（编号从 0 开始），得到反映整个二叉树结构的线性序列，再以结点编号为下标，把各结点的值存入一维数组。 对于完全二叉树，可由结点编号推出其双亲及左、右孩子的编号：编号从 0 开始时，结点 \\(i\\) 的双亲为 \\(\\lfloor \\frac{i - 1}{2} \\rfloor\\)，左孩子为 \\(2i + 1\\)，右孩子为 \\(2i + 2\\)。 二叉树的遍历分为前序（先序）、中序、后序和层次遍历。", "3、^^树所表示的数据元素关系^^：^^树是一种逻辑关系^^，表示数据元素之间存在一对多的关系。"], "title": "", "ordered": false}, {"t": "callout", "id": "a2-2-4-6-b14", "imp": "core", "kind": "tip", "text": "1. 二叉树第 i 层最多有 ==\\(2^{i-1}\\) 个节点==（\\(i \\ge 1\\)）； 2. 深度为 k 的二叉树最多有 ==\\(2^k - 1\\) 个节点==（满二叉树）； 3. ==叶子节点数 \\(n_0\\) 与度为 2 的节点数 \\(n_2\\) 永远满足黄金公式：\\(n_0 = n_2 + 1\\)==； 4. 具有 n 个节点的完全二叉树深度为 \\([\\log_2 n] + 1\\)。", "title": "考向复习提示：二叉树五大核心数学性质（必考公式）"}, {"t": "callout", "id": "a2-2-4-6-b15", "imp": "core", "kind": "trap", "text": "专转本真题经典陷阱：==仅知二叉树的“前序遍历序列 + 后序遍历序列”无法唯一确定这棵二叉树的形态结构==！必须有“==中序遍历序列==”参与（即“前序 + 中序”或“后序 + 中序”），才能唯一确定一棵二叉树的形状！", "title": "高频易错陷阱：由前序和后序遍历能否唯一确定二叉树？"}]$b85$::jsonb;
  v_search text := $s85$A2-2.4.6 树的基本概念，二叉树的定义及其存储结构，二叉树的前序、中序和后序遍历。 1、树 （1）树是一种非线性结构，是n 个结点的有限集。当n=0 时为空树，n>0 时为非空树。 ①、结点的度：结点所拥有的子树的个数，数一下分叉个数，如结点1 的有三个叉，即为3. ②、叶子结点：度为0 的结点,即没有下一代无后继无分叉。如图3，5，6，7，8 结点。 ③、分支结点：除叶子结点以外的结点。 ④、结点的层次：根结点在第一层，同一层上左右结点的子结点在下一层。 ⑤、树的深度：所处层次最大的那个结点的层次。从根节点（结点1）开始数有多少层，就是多少深度，如图上所示，有三层。即深度为3。 ⑥、树的度：树中所有结点的度的最大值。即1 结点有三个子结点（2，3，4），且为最大，度为3。 （2）二叉树是一种特殊的树形结构，每个结点最多只有两棵子树，且有左右之分不能互换，因此，二叉树有五种不同的形态。 ①、性质1 在二叉树的第k 层上，最多有2^(k-1)（k ≥ 1）个结点。 ②、性质2 深度为 m 的二叉树最多有 2^m - 1 个结点。 ③、性质3 在任意一棵二叉树中，度为0 的结点（叶子结点）总是比度为2 的结点多一个。 ④、性质4 具有 n 个结点的二叉树，其深度不小于 [log2 n] + 1，其中 [log2 n] 表示为 log2 n 的整数部分。 （3）满二叉树：除最后一层外，每一层上的所有结点都有两个子结点。 （4）完全二叉树:除最后一层外，每一层上的结点数均达到最大值；在最后一层上只缺少右边(连续)的若干结点。 ①、性质1 具有 n 个结点的完全二叉树的深度为 [log2 n] + 1。 ②、性质2 完全二叉树中度为1 的结点数为0 或1。 （5）满二叉树是完全二叉树，而完全二叉树一般不是满二叉树。 （6）二叉树遍历：前序、中序和后序 ①、前序遍历：先访问根结点、然后遍历左子树，最后遍历右子树；并且，在遍历左、右子树时，仍然先访问根结点，然后遍历左子树，最后遍历右子树。（根-左-右） 前序遍历结果：ABCDFHEG ②、中序遍历：先遍历左子树、然后访问根结点，最后遍历右子树；并且，在遍历左、右子树时，仍然先遍历左子树，然后访问根结点，最后遍历右子树。 （左-根-右） 中序遍历结果：BAFHDCGE ③、后序遍历：先遍历左子树、然后遍历右子树，最后访问根结点；并且，在遍历左、右子树时，仍然先遍历左子树，然后遍历右子树，最后访问根结点。 （左-右-根） 后序遍历结果：BHFDGECA 2、完全二叉树的顺序存储与遍历：完全二叉树的顺序存储：从树根开始自上而下、每层从左至右给每个结点编号（编号从 0 开始），得到反映整个二叉树结构的线性序列，再以结点编号为下标，把各结点的值存入一维数组。 对于完全二叉树，可由结点编号推出其双亲及左、右孩子的编号：编号从 0 开始时，结点 i 的双亲为 ⌊(i - 1)/2⌋，左孩子为 2i + 1，右孩子为 2i + 2。 二叉树的遍历分为前序（先序）、中序、后序和层次遍历。 3、树所表示的数据元素关系：树是一种逻辑关系，表示数据元素之间存在一对多的关系。 考向复习提示：二叉树五大核心数学性质（必考公式） 1. 二叉树第 i 层最多有 2^(i-1) 个节点（i ≥ 1）； 2. 深度为 k 的二叉树最多有 2^k - 1 个节点（满二叉树）； 3. 叶子节点数 n_0 与度为 2 的节点数 n_2 永远满足黄金公式：n_0 = n_2 + 1； 4. 具有 n 个节点的完全二叉树深度为 [log2 n] + 1。 高频易错陷阱：由前序和后序遍历能否唯一确定二叉树？ 专转本真题经典陷阱：仅知二叉树的“前序遍历序列 + 后序遍历序列”无法唯一确定这棵二叉树的形态结构！必须有“中序遍历序列”参与（即“前序 + 中序”或“后序 + 中序”），才能唯一确定一棵二叉树的形状！$s85$;
  v_sr jsonb := $r85${"pdf": "理论复习.pdf", "extra": ["考纲三级节点: A2-2.4.6 树的基本概念，二叉树的定义及其存储结构，二叉树的前序、中序和后序遍历。", "题库补充：完全二叉树的顺序存储与遍历 (46题)", "题库补充：树所表示的数据元素关系 (6题)"], "pages": [43, 44], "spans": 30}$r85$::jsonb;
begin
  select r.rev_no, r.html
    into old_rev
    from kb_entry e
    join kb_revision r on r.node_id = e.node_id and r.rev_no = e.published_rev
   where e.node_id = 85;

  if not found then
    raise exception 'node 85 找不到已发布 revision';
  end if;
  if old_rev.rev_no <> 4 then
    raise exception 'node 85 expected rev 4, got %', old_rev.rev_no;
  end if;

  select coalesce(max(rev_no), 0) + 1 into v_rev
    from kb_revision
   where node_id = 85;

  insert into kb_revision (node_id, rev_no, blocks, html, search_text, source_ref)
  values (85, v_rev, v_blocks, old_rev.html, v_search, v_sr);

  update kb_entry
     set published_rev = v_rev,
         updated_at = now()
   where node_id = 85;
end $$;

commit;
